import{_ as n,C as l,c as r,o as s,a9 as e,G as o}from"./chunks/framework.DuenUNqn.js";const c="/assets/noise_preview.DmrN-Ct8.png",h=JSON.parse('{"title":"噪声","description":"","frontmatter":{"breadcrumbs":[{"title":"Continue Project","link":"/wiki"},{"title":"Terra","link":"/wiki/Terra"},{"title":"config-packs","link":"/wiki/Terra/config-packs"},{"title":"config-development","link":"/wiki/Terra/config-packs/config-development"},{"title":"noise","link":"/wiki/Terra/config-packs/config-development/noise"}]},"headers":[],"relativePath":"wiki/Terra/config-packs/config-development/noise/index.md","filePath":"wiki/Terra/config-packs/config-development/noise/index.md"}'),p={name:"wiki/Terra/config-packs/config-development/noise/index.md"};function f(u,i,_,d,k,g){const t=l("NolebaseGitContributors"),a=l("NolebaseGitChangelog");return s(),r("div",null,[i[0]||(i[0]=e('<h1 id="噪声" tabindex="-1">噪声 <a class="header-anchor" href="#噪声" aria-label="Permalink to &quot;噪声&quot;">​</a></h1><figure><img src="'+c+'" alt="" tabindex="0"><figcaption></figcaption></figure><h2 id="什么是噪声" tabindex="-1">什么是噪声？ <a class="header-anchor" href="#什么是噪声" aria-label="Permalink to &quot;什么是噪声？&quot;">​</a></h2><p>从程序角度说，噪声指代一系列随机<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup>生成的值。这些值通过多种噪声算法或数学函数产生，提供了不同方式的数字值。</p><p>噪声将生成物随机放置在世界中。例如群系的生成、地形的起伏，以及诸如植被与树木的分布方式等均使用了噪声，这是一种基础的使用方式。</p><p>在 Terra 中，从某种角度上说，世界生成中的随机部分都受到了噪声的影响，因此配置与修改生成器时最好对它们有一些基础的理解。</p><h2 id="内容" tabindex="-1">内容 <a class="header-anchor" href="#内容" aria-label="Permalink to &quot;内容&quot;">​</a></h2><ul><li>配置噪声采样器 <ul><li>参数 <ul><li>普通噪声采样器参数 <ul><li>盐值</li></ul></li><li>噪声工具 <ul><li>频率</li></ul></li></ul></li><li>上下文中的采样器</li><li>其他噪声取样器方法 <ul><li>分形化</li><li>域翘曲</li></ul></li><li>采样器组成</li></ul></li><li>噪声如何随机放置生成物 <ul><li>阈值 <ul><li>植被生成</li></ul></li><li>分布列表 <ul><li>权重列表</li></ul></li></ul></li><li>噪声采样器的工作原理 <ul><li>噪声基础 <ul><li>种子</li><li>噪声采样器 <ul><li>多维度</li><li>高维度</li></ul></li><li>盐值</li><li>决定论</li><li>相干噪声 <ul><li>区别在哪？</li></ul></li><li>噪音种类</li></ul></li></ul></li></ul>',8)),o(t),o(a),i[1]||(i[1]=e('<hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>见此：<a href="https://zh.wikipedia.org/wiki/%E4%BC%AA%E9%9A%8F%E6%9C%BA%E6%95%B0%E7%94%9F%E6%88%90%E5%99%A8" target="_blank" rel="noreferrer">https://zh.wikipedia.org/wiki/伪随机数生成器</a> <a href="#fnref1" class="footnote-backref">↩︎</a></p></li></ol></section>',2))])}const T=n(p,[["render",f]]);export{h as __pageData,T as default};
